"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["61055"],{17979(e){e.exports=JSON.parse('{"id":"FIN-1166","slug":"short-interest","term":"Short Interest","also_known_as":[],"difficulty":"Advanced","definition":"Short interest is the total number of a company\'s shares that have been sold short and not yet bought back, often expressed as a percentage of the shares available for trading.","explanation":["When investors sell short, they borrow shares and sell them, hoping to buy them back later at a lower price. Short interest measures how many shares are currently held in short positions.","High short interest suggests many investors expect the share price to fall. For example, if 15% of a company\'s freely traded shares are sold short, a significant group of investors is betting against the company.","Short interest is published regularly by exchanges or regulators in many markets. In some countries, regulators also require large individual short positions to be disclosed.","High short interest can be read in different ways. It may signal real problems, such as weak finances or suspected accounting issues. But it can also lead to a short squeeze: if the price rises, short sellers rush to buy shares to limit their losses, pushing the price up further. This happened dramatically with several heavily shorted shares in early 2021. Short interest is often considered together with days to cover."],"note":"","total":1725,"prev":{"slug":"sharpe-ratio","term":"Sharpe Ratio"},"next":{"slug":"short-selling","term":"Short Selling"}}')}}]);